package udea.integrador.ingenote.infrastructure.adapter.in.rest;
import jakarta.validation.Valid; import jakarta.validation.constraints.NotNull; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import udea.integrador.ingenote.application.port.in.ValoracionUseCase; import udea.integrador.ingenote.domain.model.ResumenValoracion; import java.util.UUID;
@RestController @RequestMapping("/api/recursos/{recursoId}/valoraciones") public class ValoracionController { private final ValoracionUseCase votos; public ValoracionController(ValoracionUseCase v){votos=v;} record VotoRequest(@NotNull Short voto){} @PutMapping public ResumenValoracion votar(@PathVariable UUID recursoId,@Valid @RequestBody VotoRequest r,Authentication a){return votos.votar(a.getName(),recursoId,r.voto());} @DeleteMapping @ResponseStatus(HttpStatus.NO_CONTENT) void retirar(@PathVariable UUID recursoId,Authentication a){votos.retirar(a.getName(),recursoId);} @GetMapping public ResumenValoracion resumen(@PathVariable UUID recursoId,Authentication a){return votos.resumen(a.getName(),recursoId);}}
